feature.dataView.optionToContent.description:
```
(option:Object) => HTMLDomElement|string

```

Define a function to present dataView. It is used to replace default textarea for richer data editing. It can return a DOM object, or an HTML string.


[WARNING]: dataView panel is implemented using HTML, allowing users to customize certain parts for styling and formatting. The HTML provided by optionToContent is embedded in the panel HTML without HTML-escaping, so it should be properly escaped before being passed in. Security risks must be considered when using it. See document "Security Guidelines" for recommendations on safe usage.


For example:

```
optionToContent: function(opt) {
var axisData = opt.xAxis[0].data;
var series = opt.series;
var table = '<table style="width:100%;text-align:center"><tbody><tr>'
+ '<td>Time:</td>'
+ '<td>' + echarts.format.encodeHTML(series[0].name) + '</td>'
+ '<td>' + echarts.format.encodeHTML(series[1].name) + '</td>'
+ '</tr>';
for (var i = 0, l = axisData.length; i < l; i++) {
table += '<tr>'
+ '<td>' + echarts.format.encodeHTML(axisData[i]) + '</td>'
+ '<td>' + echarts.format.encodeHTML(series[0].data[i]) + '</td>'
+ '<td>' + echarts.format.encodeHTML(series[1].data[i]) + '</td>'
+ '</tr>';
}
table += '</tbody></table>';
return table;
}

```

feature.magicType.description:
Magic type switching.
示例:

```
feature: {
magicType: {
type: ['line', 'bar', 'stack']
}
}

```

tooltip.description:
Tooltip configuration for toolbox tooltip, which is similar to tooltip . It is not shown by default. If you wish to set special style for toolbox icon label (especially when using CSS to control text style), you may set as the following example:

```
option = {
tooltip: {
show: true // include tooltip component for the feature
},
toolbox: {
show: true,
showTitle: false, // hide the default text so they don't overlap each other
feature: {
saveAsImage: {
show: true,
title: 'Save As Image'
},
dataView: {
show: true,
title: 'Data View'
},
},
tooltip: { // same as option.tooltip
show: true,
formatter: function (param) {
return '<div>' + param.title + '</div>'; // user-defined DOM structure
},
backgroundColor: '#222',
textStyle: {
fontSize: 12,
},
extraCssText: 'box-shadow: 0 0 3px rgba(0, 0, 0, 0.3);' // user-defined CSS styles
}
},
...
}

```
